#!/usr/bin/env python3
"""Standalone reader for original panoramas, complete answers and verified votes."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'stage04_doorway_cases'
TEMPLATE=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>HOHONET — Late population response evidence</title>
<style>body{font:16px/1.6 system-ui,sans-serif;color:#17212b;background:#f3f5f7;margin:0}main{max-width:1400px;margin:auto;padding:24px}h1{font-size:28px;margin:0 0 8px}h2{font-size:21px}section{background:white;border:1px solid #d7dfe5;border-radius:10px;padding:18px;margin:15px 0}.controls{display:flex;gap:14px;flex-wrap:wrap;align-items:center}select,button{font:inherit;padding:6px;max-width:450px}canvas{width:100%;background:#f8fafc;border:1px solid #c7d1dc}.two{display:grid;grid-template-columns:1fr 1fr;gap:20px}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border-bottom:1px solid #dae0e6;text-align:left;padding:6px}th{background:#eff4f8}tbody tr:hover{background:#fff2de;cursor:pointer}.muted{color:#56616c;font-size:14px}.blue{color:#2878b5}.orange{color:#d95f02}.purple{color:#9c27b0}.tag{border:1px solid #98a7b5;border-radius:4px;padding:2px 6px;margin-right:8px}pre{white-space:pre-wrap;font-size:12px;overflow-wrap:anywhere}.scroll{max-height:450px;overflow:auto}@media(max-width:800px){.two{grid-template-columns:1fr}main{padding:12px}}</style>
<main><h1>HOHONET v2.1：逐图后段人数变化的完整证据</h1><p>本页读取当前 584／439 版本的精确团队、原答与最终参考。两例取对应人数增量的 256 条路径中质量变化中位数附近的实际路径。原图、原答、已选／未选身份组、位置与连接均可检查。</p>
<section><div class="controls"><label>案例 <select id="case"></select></label><span id="meta"></span></div><p id="summary"></p><p class="muted">蓝色为较少人数；橙色为较多人数；深灰为采用参考；紫色为所选人员的完整标注。身份组编号只在该端点内有效，跨队通过原答点对对应。</p></section>
<section><div class="controls"><label>原答 <select id="raw"></select></label><label>票账端点 <select id="side"><option value="low">较少人数</option><option value="high">较多人数</option></select></label><label>身份组 <select id="group"></select></label></div>
<div class="controls"><label><input type="checkbox" id="showref" checked> 参考</label><label><input type="checkbox" id="showlow" checked> 较少人数输出</label><label><input type="checkbox" id="showhigh" checked> 较多人数输出</label><label><input type="checkbox" id="showgroup" checked> 所选组全部来源点对</label></div><p id="rawinfo" class="muted"></p><canvas id="panorama" width="2048" height="1024"></canvas><p class="muted">连接线按已保存角点的空间直线投影，仅用于查看。未改变原答、融合点、参考或正式指标。可将原答下拉切为任意成员，包括当前筛除人员；筛除人员不会因此进入研究团队。</p></section>
<section class="two"><div><h2>Bottom-plane geometry</h2><canvas id="plan" width="700" height="550"></canvas></div><div><h2>Quality and components</h2><table id="metrics"></table><p id="status" class="muted"></p></div></section>
<section class="two"><div><h2>全部身份组（含未入选）</h2><p class="muted">点击一行查看该组来源点对、群中心和成员。门槛针对局部身份组；完整来源环的支持数单独列出。</p><div class="scroll"><table id="votes"></table></div></div><div><h2>所选组的实际原答</h2><pre id="groupinfo"></pre><h2>连接与完整来源环</h2><pre id="connection"></pre></div></section>
<section><h2>跨端点原答点对流向</h2><p class="muted">此表只计两队共有原答点对，新进入者不计入共享数量。一个旧组可拆到多个新组，多个旧组也可并入一个新组，因此不把同编号当作同一结构。</p><div class="scroll"><table id="flow"></table></div></section>
<section><h2>证据有效性</h2><p>3 个缺失轨迹采用冻结规则诊断回放，另 1 个复用已保存完整轨迹。四端点的几何、输出状态、门槛、选中支持票以及 B8L2／D10／IoU3D100 与当前缓存逐项一致。未新增自然路径，未替换正式结果。</p><p>高人数只反映该有限人员池；满员只有一队，不代表正确或人人一致。右侧柜体／门框交界、卧室与洗衣／浴室边界的语义范围仍应按照本轮固定参考解释，不能单凭低 Q 判定标注者乱标或 GT 错误。</p></section></main>
<script>const DATA=__DATA__;
const $=x=>document.getElementById(x);let current=DATA[0],photo=new Image();const COLORS={low:'#2878b5',high:'#d95f02',ref:'#17212b',raw:'#9c27b0'};
DATA.forEach((x,i)=>$('case').add(new Option(x.meta.image+' · '+x.meta.low_k+' → '+x.meta.high_k,i)));
function group(){const v=$('group').value;return v===''?null:current[$('side').value].full_state.identity_groups[+v]}
function raw(){return $('raw').value===''?null:current.raw[+$('raw').value]}
function ring3(points){let b=[],t=[];for(let i=0;i<points.length;i+=2){let top=points[i],bot=points[i+1],u=2*Math.PI*bot[0]/1024,r=1/Math.tan(Math.PI*(bot[1]/512-.5));let x=-r*Math.sin(u),z=r*Math.cos(u);b.push([x,-1,z]);t.push([x,r*Math.tan(Math.PI*(.5-top[1]/512)),z])}return [b,t]}
function project(v){let r=Math.hypot(v[0],v[2]);return [((Math.atan2(-v[0],v[2])/(2*Math.PI)*1024)%1024+1024)%1024,512*(.5-Math.atan2(v[1],r)/Math.PI)]}
function drawLayout(ctx,points,color,lw,alpha=1){if(!points||!points.length)return;ctx.save();ctx.strokeStyle=color;ctx.fillStyle=color;ctx.lineWidth=lw;ctx.globalAlpha=alpha;let rings=ring3(points);for(let ring of rings){for(let i=0;i<ring.length;i++){let a=ring[i],b=ring[(i+1)%ring.length],last=null;ctx.beginPath();for(let j=0;j<=40;j++){let f=j/40,p=project(a.map((v,k)=>v*(1-f)+b[k]*f));if(last&&Math.abs(p[0]-last[0])<512)ctx.lineTo(...p);else ctx.moveTo(...p);last=p}ctx.stroke()}}for(let i=0;i<points.length;i+=2){ctx.beginPath();ctx.moveTo(...points[i]);ctx.lineTo(...points[i+1]);ctx.stroke();for(let j=0;j<2;j++){ctx.beginPath();ctx.arc(...points[i+j],2,0,2*Math.PI);ctx.fill()}}ctx.restore()}
function refreshGroups(){let s=current[$('side').value].full_state;$('group').innerHTML='';$('group').add(new Option('不聚焦单组',''));s.identity_groups.forEach((g,i)=>$('group').add(new Option(`${g.feature_id}: ${g.support}/${s.n} · ${g.selected?'入选':'未入选'}`,i)));render()}
function render(){const ctx=$('panorama').getContext('2d');ctx.setTransform(2,0,0,2,0,0);ctx.clearRect(0,0,1024,512);if(photo.complete)ctx.drawImage(photo,0,0,1024,512);
if($('showref').checked)drawLayout(ctx,current.reference.points_1024x512,COLORS.ref,1.5,.9);for(let side of ['low','high'])if($('show'+side).checked)drawLayout(ctx,current[side].full_state.candidate.points,COLORS[side],1.3,.95);
let rr=raw();if(rr){drawLayout(ctx,rr.points,COLORS.raw,1.3,1);$('rawinfo').textContent=`${rr.worker} · ${rr.points.length/2} 点对 · ${rr.in_current_after_pool?'保留在当前筛后池':'不在当前筛后池'} · object_id=${rr.object_id}`}else $('rawinfo').textContent='选择任意人员，显示其完整原答（不截取局部门洞点）。';
let gg=group();if(gg&&$('showgroup').checked){ctx.save();ctx.strokeStyle='#bb00aa';ctx.lineWidth=.65;ctx.globalAlpha=.6;gg.members.forEach(m=>{ctx.beginPath();ctx.moveTo(...m.points[0]);ctx.lineTo(...m.points[1]);ctx.stroke()});ctx.globalAlpha=1;ctx.strokeStyle='#e00000';ctx.lineWidth=2.7;ctx.setLineDash([4,3]);ctx.beginPath();ctx.moveTo(...gg.center[0]);ctx.lineTo(...gg.center[1]);ctx.stroke();ctx.restore()}
const pc=$('plan').getContext('2d');pc.clearRect(0,0,700,550);let shapes=[{p:current.reference.floor_xz_h,c:COLORS.ref,n:'Reference'},{p:current.low.full_state.candidate.footprint,c:COLORS.low,n:'Before'},{p:current.high.full_state.candidate.footprint,c:COLORS.high,n:'After'}];if(rr)shapes.push({p:ring3(rr.points)[0].map(v=>[v[0],v[2]]),c:COLORS.raw,n:rr.worker});let ps=shapes.flatMap(s=>s.p).concat([[0,0]]),xs=ps.map(v=>v[0]),zs=ps.map(v=>v[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),zmin=Math.min(...zs),zmax=Math.max(...zs),scale=Math.min(610/(xmax-xmin||1),440/(zmax-zmin||1));let tr=p=>[45+(p[0]-xmin)*scale,495-(p[1]-zmin)*scale];shapes.forEach((s,i)=>{pc.strokeStyle=s.c;pc.lineWidth=2.3;pc.beginPath();s.p.concat([s.p[0]]).forEach((p,j)=>j?pc.lineTo(...tr(p)):pc.moveTo(...tr(p)));pc.stroke();pc.fillStyle=s.c;pc.font='16px system-ui';pc.fillText(s.n,30+i*145,25)});let cp=tr([0,0]);pc.fillStyle='black';pc.beginPath();pc.arc(...cp,4,0,2*Math.PI);pc.fill();pc.fillText('Camera',cp[0]+6,cp[1]);pc.font='13px system-ui';pc.fillText('Coordinates are normalized by camera height; plan scale follows displayed layouts.',25,535);
let state=current[$('side').value].full_state;$('votes').innerHTML='<tr><th>Group</th><th>Support / k</th><th>Threshold</th><th>Selected</th></tr>'+state.identity_groups.map((g,i)=>`<tr data-g="${i}"><td>${g.feature_id}</td><td>${g.support}/${state.n}</td><td>${state.minimum_support}</td><td>${g.selected?'Yes':'No'}</td></tr>`).join('');$('votes').querySelectorAll('[data-g]').forEach(x=>x.onclick=()=>{$('group').value=x.dataset.g;render()});$('groupinfo').textContent=gg?JSON.stringify({group:gg.feature_id,support:gg.support,selected:gg.selected,center:gg.center,members:gg.members.map(m=>({worker:m.worker,object_id:m.id,pair_index:m.pair_index,source_pair_index:m.source_pair_index,points:m.points}))},null,2):'请选择身份组。';$('connection').textContent=JSON.stringify({policy:state.ring_diagnostics.policy,chosen_ring:state.ring_diagnostics.feature_ids,alternatives:state.ring_diagnostics.alternatives,edges:state.ring_diagnostics.edges},null,2);
}
function selectCase(){current=DATA[+$('case').value];let m=current.meta;$('meta').textContent=`N=${m.N} · replicate ${m.base_replicate} · 最后进入 ${m.new_worker}`;$('summary').textContent=`256 路径平均 ΔB8L2=${m.path_mean_delta_B8.toFixed(3)}；所示路径 Δ=${m.selected_delta_B8.toFixed(3)}。采用目标：${m.target_id}。`;$('raw').innerHTML='';$('raw').add(new Option('不显示个人叠加',''));current.raw.forEach((r,i)=>$('raw').add(new Option(`${r.worker} · ${r.points.length/2} pairs · ${r.in_current_after_pool?'after pool':'outside after pool'}`,i)));$('metrics').innerHTML='<tr><th>Metric</th><th>Before</th><th>After</th><th>Delta</th></tr>'+current.metrics.map(x=>`<tr><td>${x.metric}</td><td>${x.before.toFixed(4)}</td><td>${x.after.toFixed(4)}</td><td>${x.delta.toFixed(4)}</td></tr>`).join('');$('status').textContent='两端均完整可评；数据使用既有固定参考。下降型损失指标应结合其原定义解释，不能把所有正差都称为改善。';$('flow').innerHTML='<tr><th>Before group</th><th>After group</th><th>Shared pairs</th><th>Before selected</th><th>After selected</th></tr>'+current.flow.map(x=>`<tr><td>${x.low_group}</td><td>${x.high_group}</td><td>${x.shared_original_point_pairs}</td><td>${x.low_selected}</td><td>${x.high_selected}</td></tr>`).join('');photo=new Image();photo.onload=render;photo.src=current.photo;refreshGroups()}
$('case').onchange=selectCase;$('side').onchange=refreshGroups;['raw','group','showref','showlow','showhigh','showgroup'].forEach(x=>$(x).onchange=render);selectCase();</script></html>'''

data=json.loads((OUT/'CASE_VIEWER_DATA.json').read_text())
html=TEMPLATE.replace('__DATA__',json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('</','<\\/'))
(OUT/'DOORWAY_LATE_RESPONSE_EVIDENCE.html').write_text(html)
print('Standalone viewer bytes',len(html.encode()))
